147:                     return Alarm(infoText, caption, buttonTexts, drs, alarmLevel);
148:                 }
149:             }
150:         }

163:         private static DialogResult Alarm(
164:             string infoText,
165:             string caption,
166:             string[] buttonTexts,
167:             DialogResult[] drs,
168:             AlarmLevel alarmLevel = AlarmLevel.SecondLevel)
169:         {
