171:             alarmLog.StartTime = DateTime.Now;
172:             alarmLog.Message = infoText;
173: 
174:             DialogResult dr = DialogResult.Abort;
175: 
176:             if (MainForm.SendUiAction == null)
177:             {
178:                 AKRSMessageBox msg = new AKRSMessageBox(infoText, caption, buttonTexts, drs, AlarmLevel.SecondLevel);
179:                 msgBoxDict.Add(msg.Guid, msg);
180:                 msg.TopMost = false;
181:                 dr = msg.ShowDialog();
182:                 msgBoxDict.Remove(msg.Guid);
183:                 SetAlarmState();
184:                 msg.Dispose();
185:             }
186:             else
187:             {
188:                 MainForm.SendUiAction(
189:                    () =>
190:                    {
191:                        AKRSMessageBox msg = new AKRSMessageBox(infoText, caption, buttonTexts, drs, AlarmLevel.SecondLevel);
192:                        msgBoxDict.Add(msg.Guid, msg);
193:                        msg.TopMost = false;
194:                        dr = msg.ShowDialog();
195:                        msgBoxDict.Remove(msg.Guid);
196:                        SetAlarmState();
197:                        msg.Dispose();
198:                    });
