61:         public AKRSPoint3D RealTimeVision(AKRSPoint3D point3D)
62:         {
63:             if (ReferencePoints == null)
64:             {
65:                 throw new ArgumentNullException("实时补偿没有数据");
66:             }
67: 
68:             if (point3D == null)
69:             {
70:                 throw new ArgumentNullException("实时补偿传入点位为空");
71:             }
72: 
73:             #region 获取最近的两个点
74: 
75:             // 寻找离坐标最近的两个点
76:             AKRSPoint3D point3DRight = (AKRSPoint3D)ReferencePoints.Find(it => it.X > point3D.X);
77: 
78:             if (point3DRight == null)
79:             {
80:                 throw new ArgumentNullException("实时补偿传入数据X过大，未找到补偿点位");
81:             }
82: 
83:             // 索引
84:             int index = ReferencePoints.IndexOf(point3DRight);
85: 
86:             if (index == 0)
87:             {
88:                 throw new ArgumentNullException("实时补偿传入数据X过小，未找到补偿点位");
89:             }
90: 
91:             AKRSPoint3D point3DLeft = ReferencePoints[index - 1];
92: 
93:             #endregion
94: 
95:             #region 定位
96: 
97:             MatchResult matchResultRight = (MatchResult)System2Domain.GetInstance().System2CommonVision(point3DRight, PrName, PrName);
98: 
99:             if (matchResultRight == null)
100:             {
101:                 throw new Exception("实时补偿定位失败");
102:             }
103: 
104:             AKRSPoint3D posRight = System2Domain.GetInstance().BondModuleController.ConvertPixelToG0Pos(System2Domain.GetInstance().BondModuleController.Get3DRealPosition(), matchResultRight);
105: 
106:             MatchResult matchResultLeft = (MatchResult)System2Domain.GetInstance().System2CommonVision(point3DLeft, PrName, PrName);
107: 
108:             if (matchResultLeft == null)
109:             {
110:                 throw new Exception("实时补偿定位失败");
111:             }
112: 
113:             AKRSPoint3D posLeft = System2Domain.GetInstance().BondModuleController.ConvertPixelToG0Pos(System2Domain.GetInstance().BondModuleController.Get3DRealPosition(), matchResultLeft);
114: 
115:             #endregion
116: 
117:             #region 计算结果
118: 
119:             double distance = point3DRight.X - point3DLeft.X;
120: 
121:             // 右边比例
122:             double rightRatio = 1 - (point3DRight.X - point3D.X) / distance;
123: 
124:             // 左边比例
125:             double leftRatio = 1 - (point3D.X - point3DLeft.X) / distance;
126: 
127:             // 总的补偿值
128:             AKRSPoint3D compensate = (posRight - point3DRight) * rightRatio + (posLeft - point3DLeft) * leftRatio;
129: 
130:             if (Math.Abs(compensate.X) > 0.5 || Math.Abs(compensate.Y) > 0.5)
131:             {
132:                 throw new ArgumentNullException("实时补偿获取数据过大，请检查标定点是否发生改变");
133:             }
134: 
135:             return compensate;
136: 
137:             #endregion
138:         }

149:         public AKRSPoint3D GetCompensatePoint3D(AKRSPoint3D iptPickPos, AKRSPoint3D iptVisionPos, AKRSPoint3D bondPos, AKRSPoint3D bondVisonPos) 
150:         {
151:             //return new AKRSPoint3D(/*compensate.X*/0, 0, 0);
152: 
153:             try
154:             {
155:                 System2RunTimeProvider.RecordTime("BondAction", "获取补偿值开始 ----------------");
156: 
157:                 if (!System2Configuration.GetInstance().IsRealTimeCompensate)
158:                 {
159:                     return new AKRSPoint3D();
160:                 }
161: 
162:                 if (iptPickPos == null || iptVisionPos == null || bondPos == null || bondVisonPos == null)
163:                 {
164:                     throw new ArgumentNullException("实时补偿矫正传入数据为空");
165:                 }
166: 
167:                 if (this.ReferencePoints == null || this.ReferencePointsCompensate == null)
168:                 {
169:                     throw new ArgumentNullException("实时补偿矫正本地数据为空");
170:                 }
171: 
172:                 if (!this.IsAssistanted)
173:                 {
174:                     throw new ArgumentNullException("实时补偿矫正未示教");
175:                 }
176: 
177:                 AKRSPoint3D iptPickPosCompensate = this.GetCompensatePosByPoint(iptPickPos);
178:                 AKRSPoint3D iptVisionPosCompensate = this.GetCompensatePosByPoint(iptVisionPos);
179:                 AKRSPoint3D bondPosCompensate = this.GetCompensatePosByPoint(bondPos);
180:                 AKRSPoint3D bondVisonPosCompensate = this.GetCompensatePosByPoint(bondVisonPos);
181: 
182:                 AKRSPoint3D compensate = (iptPickPosCompensate - iptVisionPosCompensate) - (bondPosCompensate - bondVisonPosCompensate);
183: 
184:                 if (Math.Abs(compensate.X) > 0.5 || Math.Abs(compensate.Y) > 0.5)
185:                 {
186:                     return new AKRSPoint3D(/*compensate.X*/0, 0, 0);
187:                 }
188: 
189:                 //return compensate;
190: 
191:                 System2RunTimeProvider.RecordTime("BondAction", "获取补偿值结束 ----------------");
192: 
193:                 return new AKRSPoint3D(compensate.X, 0, 0);
194:             }
195:             catch (Exception ex)
196:             {
197: 
198:                 throw new Exception(ex.Message);
199:             }
200: 
201:         }

208:         private AKRSPoint3D GetCompensatePosByPoint(AKRSPoint3D point3D)
209:         {
210:             #region 获取最近的两个点
211: 
212:             AKRSPoint3D point3DRight = null;
213: 
214:             if (point3D.X >= this.ReferencePoints.Max(it => it.X))
215:             {
216:                 point3DRight = this.ReferencePoints[this.ReferencePoints.Length - 1];
217:             }
218:             else
219:             {
220:                 // 寻找离坐标最近的两个点
221:                 point3DRight = (AKRSPoint3D)this.ReferencePoints.Find(it => it.X > point3D.X);
222:             }
223: 
224:             if (point3DRight == null)
225:             {
226:                 throw new ArgumentNullException("实时补偿传入数据X过大，未找到补偿点位");
227:             }
228: 
229:             // 索引
230:             int index = this.ReferencePoints.IndexOf(point3DRight);
231: 
232:             if (index == 0)
233:             {
234:                 throw new ArgumentNullException("实时补偿传入数据X过小，未找到补偿点位");
235:             }
236: 
237:             AKRSPoint3D point3DLeft = this.ReferencePoints[index - 1];
238: 
239:             AKRSPoint3D posRight = this.ReferencePointsCompensate[index];
240: 
241:             AKRSPoint3D posLeft = this.ReferencePointsCompensate[index - 1];
242: 
243:             #endregion
244: 
245:             #region 计算结果
246: 
247:             double distance = point3DRight.X - point3DLeft.X;
248: 
249:             // 右边比例
250:             double rightRatio = 1 - (point3DRight.X - point3D.X) / distance;
251: 
252:             // 左边比例
253:             double leftRatio = 1 - (point3D.X - point3DLeft.X) / distance;
254: 
255:             // 总的补偿值
256:             AKRSPoint3D compensate = (posRight - point3DRight) * rightRatio + (posLeft - point3DLeft) * leftRatio;
257: 
258:             if (Math.Abs(compensate.X) > 0.5 || Math.Abs(compensate.Y) > 0.5)
259:             {
260:                 throw new ArgumentNullException("实时补偿获取数据过大，请检查标定点是否发生改变");
261:             }
262: 
263:             return compensate;
264: 
265:             #endregion
266:         }

