156:         public override ExcuteResult DoWork()
157:         {
158:             System2RunTimeProvider.RecordTime("PickAction", "Start ----------------");
159: 
160:             if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.OffLineWork)
161:             {
162:                 return ExcuteResult.Success;
163:             }
164: 
165:             try
166:             {
167:                 this.PrepareBeforePickAction();
168: 
169:                 // 换吸嘴
170:                 ExcuteResult ret = this.JudgeAndChangeNozzle();
171:                 if (ret != ExcuteResult.Success)
172:                 {
173:                     return ret;
174:                 }
175: 
176:                 // 擦拭吸嘴
177:                 this.JudgeAndCleanNozzle();
178: 
179:                 // 空跑
180:                 if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.DryCycle)
181:                 {
182:                     return this.PickActionDryRun();
183:                 }
184: 
185:                 // 取片温漂补偿
186:                 if (!TpMarkCompensate.PickUpCompensationVision(true))
187:                 {
188:                     return ExcuteResult.Abort;
189:                 }
190: 
191: 
192:                 AKRSPoint3D pickCompensation = TpMarkCompensate.GetPickCompensation();
193: 
194:             #region 定位并计算取料位
195: 
196:             NextDie:
197: 
198:                 // 静态华夫盒芯片定位结果
199:                 MatchResult matchResult = null;
200: 
201:                 // 芯片定位角度
202:                 double componentAngle = default;
203: 
204:                 System2RunTimeProvider.RecordTime("PickAction", $"判断吸嘴有无芯片完成 - 开始等待晶圆允许取料信号,当前芯片名称{this.component.Name}");
205: 
206:                 if (!MachineStateModel.GetInstance().IsCompensateWork)
207:                 {
208:                     // 允许取料信号判断（从信号池获取）,这个信号会自动复位
209:                     if (System2RunTimeProvider.WaitAllowBondPickSignal(component) != ExcuteResult.Success)
210:                     {
211:                         return ExcuteResult.Abort;
212:                     }
213:                 }
214: 
215:                 System2RunTimeProvider.RecordTime("PickAction", $"开始等待晶圆允许取料信号 -- 等待晶圆允许取料信号完成,当前芯片名称{this.component.Name}");
216: 
217:                 // 芯片Total数加一
218:                 component.AddCountOfTotal();
219: 
220:                 // 静态华夫盒：定位并获取芯片定位角度
221:                 if (component.CarrierType == CarrierTypeEnum.StaticWaffle)
222:                 {
223:                     // 静态华夫盒定位
224:                     (ExcuteResult res, MatchResult matchResult) result = this.StaticWaffleVision(this.isSkipComponent);
225: 
226:                     switch (result.res)
227:                     {
228:                         case ExcuteResult.Abort:
229:                             return ExcuteResult.Abort;
230: 
231:                         case ExcuteResult.Success:
232: 
233:                             // 保存结果
234:                             matchResult = result.matchResult;
235:                             componentAngle = result.matchResult.Angle;
236:                             break;
237: 
238:                         case ExcuteResult.Retry:
239: 
240:                             // 下一颗
241:                             goto NextDie;
242: 
243:                         default:
244:                             return result.res;
245:                     }
246:                 }
247:                 else
248:                 {
249:                     if (component.SearchCamera == SearchCameraEnum.BondCamera)
250:                     {
251:                        ExcuteResult excuteResult = this.MoveToSearchPosAndWaitSignal(component.BondCameraSearchPosition);
252: 
253:                        if (excuteResult != ExcuteResult.Success)
254:                        {
255:                            return excuteResult;
256:                        }
257:                     }
258: 
259:                     // 获取芯片定位角度
260:                     componentAngle = WaferSystemDomain.GetInstance().Block.GetBondSpinAngle();
261:                 }
262: 
263:                 bp.BondPositionInfo.ComponentAngleOnWafer = componentAngle;
264: 
265:                 // 计算最终取晶位
266:                 AKRSPoint4D curPickPos = this.system2Controller.CalculatePickPos(component, componentAngle, matchResult);
267: 
268:                 #endregion
269: 
270:                 #region 去取料位
271: 
272:                 // 取片前准备，主要是真空
273:                 this.system2Controller.PrepareBeforePick(component);
274: 
275:                 // 预取片位
276:                 AKRSPoint4D prePickPos = new AKRSPoint4D()
277:                 {
278:                     X = curPickPos.X + pickCompensation.X,
279:                     Y = curPickPos.Y + pickCompensation.Y,
280:                     Z = component.IsActivateSlowTravelBeforePickup
281:                                                          ? curPickPos.Z + component.SlowTravelDistanceBeforePickup
282:                                                          : curPickPos.Z,
283:                     T = curPickPos.T
284:                 };
285: 
286:                 // 获取安全高度
287:                 double liftSafeLevel = this.bondModuleController.GetBondheadSafeLevel(prePickPos);
288: 
289:                 // 去预取片位
290:                 ExcuteResult res = this.MoveToPrePickPos(
291:                     prePickPos,
292:                     liftSafeLevel,
293:                     component.CarrierType,
294:                     component.SearchCamera);
295: 
296:                 if (res != ExcuteResult.Success)
297:                 {
298:                     return res;
299:                 }
300: 
301:                 #endregion
302: 
303:                 // 开始设置力控实时曲线
304:                 this.StartSetBondForceRealTimeCurve();
305: 
306:                 // 保存取片力值
307:                 this.StartCollectPickupForce();
308: 
309:                 // 取片前检查
310:                 ExcuteResult checkRes = this.CheckBeforePick(component);
311:                 if (checkRes != ExcuteResult.Success)
312:                 {
313:                     return checkRes;
314:                 }
315: 
316:                 #region 取料
317: 
318:                 // 取料类型
319:                 PickTypeEnum pickType;
320: 
321:                 if (component.IsUseFlipTable)
322:                 {
323:                     pickType = PickTypeEnum.FlipTable;
324:                 }
325:                 else
326:                 {
327:                     // 判断芯片类型
328:                     pickType = component is CarrierWithWaferConfig ? PickTypeEnum.CarrierWithWafer : PickTypeEnum.CarrierWithWaffle;
329:                 }
330: 
331:             Repick:
332: 
333:                 // 执行Pick方法
334:                 ExcuteResult pickRes = this.Pick(curPickPos.Z, pickType);
335: 
336:                 switch (pickRes)
337:                 {
338:                     case ExcuteResult.Success:
339:                         Static.IsComponentOnFlipTool = false;
340:                         break;
341: 
342:                     case ExcuteResult.Abort:
343:                         return ExcuteResult.Abort;
344: 
345:                     case ExcuteResult.Exception:
346: 
347:                         // 顶针缩回
348:                         WaferSubController.GetInstance().EjectController.MoveEjectToReadyLiftPositionAndBlow();
349: 
350:                         return ExcuteResult.Exception;
351:                 }
352: 
353:                 //this.StopSetBondForceRealTimeCurve();
354: 
355:                 #endregion
356: 
357:                 // 被顶起的芯片+1
358:                 component.AddCountOfUseable();
359:                 WaferSubController.GetInstance().EjectController.AddCountOfUseable();
360: 
361:                 #region 漏晶检测
362: 
363:                 // 空跑模式不检测
364:                 if (MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle)
365:                 {
366:                 ReCheckVacuum:
367: 
368:                     if (component.IsActiveComponentDetection)
369:                     {
370:                         // 检测真空
371:                         if (!this.bondHeadController.ComponentCheckAfterPickup(this.bondHeadController.GetCurrentNozzle()))
372:                         {
373:                             // 真空报警芯片+1
374:                             component.AddCountOfVacuumError();
375: 
376:                             DialogResult dialogResult = AKRSMessageBoxExt.Show(
377:                                 $"取片失败:检测到漏精！请选择如何处理! \r\n",
378:                                 "真空报警",
379:                                 new string[] { "重新检测", "退出", "忽略", "重取", "下一颗" },
380:                                 new DialogResult[]
381:                                     {
382:                                         DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore,
383:                                         DialogResult.Cancel, DialogResult.Yes
384:                                     },
385:                                 AlarmLevel.SecondLevel);
386: 
387:                             switch (dialogResult)
388:                             {
389:                                 case DialogResult.Retry:
390:                                     goto ReCheckVacuum;
391: 
392:                                 case DialogResult.Abort:
393:                                     return ExcuteResult.Abort;
394: 
395:                                 case DialogResult.Ignore:
396:                                     break;
397: 
398:                                 case DialogResult.Cancel:
399:                                     goto Repick;
400: 
401:                                 // 下一颗
402:                                 case DialogResult.Yes:
403: 
404:                                     this.bondModuleController.ThrowAction();          
405: 
406:                                     // 给翻转台发信号
407:                                     if (component.IsUseFlipTable)
408:                                     {
409:                                         string nextComponentName = actionNodesService.GetNextComponentName();
410: 
411:                                         // 判断是不是最后一颗芯片
412:                                         if (nextComponentName == null)
413:                                         {
414:                                             if (this.component.CarrierType == CarrierTypeEnum.Wafer)
415:                                             {
416:                                                 // 顶针缩回
417:                                                 WaferSubController.GetInstance().EjectController.MoveEjectToReadyLiftPositionAndBlow();
418:                                             }
419: 
420: 
421:                                             // 发要料信号
422:                                             // 刷新Map信息
423:                                             WaferSystemDomain.GetInstance().Block.RefreshMap();
424: 
425:                                             // 芯片名称传给晶圆台
426:                                             WaferSystemDomain.GetInstance().WaferSubSystemTask.SetCurrentNeedChipName(component.Name);
427: 
428:                                             // 给晶圆台发要料信号
429:                                             SignalPool.GetInstance().IsBondNeedChipSignal.Set();
430: 
431:                                             Static.RecordTime("取片信号交互", $"取片完成，给晶圆发要料信号，芯片名称{component.Name}");
432:                                         }
433: 
434:                                         SignalPool.GetInstance().IsBondPickSucceedSignal.Set();
435:                                     }
436:                                     else
437:                                     {
438:                                         // 刷新Map信息
439:                                         WaferSystemDomain.GetInstance().Block.RefreshMap();
440: 
441:                                         // 芯片名称传给晶圆台
442:                                         WaferSystemDomain.GetInstance().WaferSubSystemTask.SetCurrentNeedChipName(component.Name);
443: 
444:                                         // 给晶圆台发要料信号
445:                                         SignalPool.GetInstance().IsBondNeedChipSignal.Set();
446:                                     }
447: 
448:                                     System2RunTimeProvider.IsRepickComponent = true;
449: 
450:                                         System2RunTimeProvider.RecordTime("取片信号交互", $"取片失败，给晶圆发要料信号，芯片名称{component.Name}");
451: 
452:                                     goto NextDie;
453:                             }
454:                         }
455:                     }
456:                 }
457: 
458:                 #endregion
459: 
460:                 System2RunTimeProvider.IsMaterialOnBondhead = true;
461: 
462:                 Task.Run(
463:                         () =>
464:                         {
465:                             CommonUtil.SetCurrentThreadName("提前设置上视/下视灯光");
466: 
467:                             this.SetAcurracyCameraLight();
468:                         });
469: 
470:                 // 这里阻塞是为了防止点暂停的时候晶圆台移动
471:                 if (Signal.WaitStart() == false)
472:                 {
473:                     return ExcuteResult.Abort;
474:                 }
475: 
476:                 // 翻转台芯片不在这这里发信号。会挡晶圆相机视野
477:                 if (component.IsUseFlipTable == false)
478:                 {
479:                     Task.Run(
480:                                            () =>
481:                                            {
482:                                                CommonUtil.SetCurrentThreadName("给晶圆发要料信号线程");
483: 
484:                                                if (!MachineStateModel.GetInstance().IsCompensateWork)
485:                                                {
486:                                                    this.SendSignalToWaferTable();
487:                                                }
488:                                            });
489:                 }
490:                 else
491:                 {
492:                     Task.Run(
493:                                            () =>
494:                                            {
495:                                                CommonUtil.SetCurrentThreadName("给翻转台发取料成功信号线程");
496: 
497:                                                this.SendSignalToFlipTable();
498:                                            });
499:                 }
500: 
501:                 System2RunTimeProvider.RecordTime("PickAction", "Action 完成");
502:                 return ExcuteResult.Success;
503:             }
504:             catch (Exception ex)
505:             {
506:                 LogHelper.Post(Level.Info, $"流程{this.Name}运行故障", ex, LogCategory.Bond);
507:                 AKRSMessageBoxExt.Show(ex.Message, "Exception", new string[] { "Exception" }, new DialogResult[] { DialogResult.Yes });
508:                 return ExcuteResult.Exception;
509:             }
510:             finally
511:             {
512:                 this.State = RunStateEnum.Stop;
513:                 this.WorkStop?.Invoke();
514:             }
515:         }

