151:                     return this.PostBondActionDryRun();
152:                 }
153: 
154:                 // 胶量检测
155:                 if (PostBondInspection.ApplicationSystem == PostBondApplicationSystemEnum.EpoxyCheck)
156:                 {
157:                     // 芯片点位1定位
158:                     AKRSPoint3D visionPos1 =
159:                         BondPosition.CoordinateSystem.SelfPosToG0(this.PostBondInspection.VisionConfig.P1VisionPos)
160:                         - BondDevicePara.GetInstance().BondHeadParam.HeadToCameraOffset;
161: 
162:                     // 去拍照位置执行拍照
163:                     List<BaseAlgResult> baseAlgResults = this.system2Controller.BondCameraVisionDefect(
164:                         visionPos1,
165:                         this.PostBondInspection.VisionConfig.P1PRName, false, true);
166: 
167:                     // 结果检测
168:                     return this.EpoxyApplicationDefect(baseAlgResults);
169:                 }
170:                 else if (PostBondInspection.ApplicationSystem == PostBondApplicationSystemEnum.AfterBondCheck)
171:                 {
172:                     // 焊后检测
173:                     switch (PostBondInspection.PostBondInspectionMode)
174:                     {
175:                         // 如果是没有参考点的情况下定位
176:                         case PostBondInspectionModeEnum.WithoutReferenceSearch:
177: 
178:                             #region 一点定位，无参考点
179: 
180:                             AKRSPoint4D g0Point4D1 = this.DefectVision(
181:                                 this.PostBondInspection.VisionConfig.P1VisionPos,
182:                                 this.PostBondInspection.VisionConfig.P1PRName);
183: 
184:                             if (PostBondInspection.MeasurePointNumber == MeasurePointNumberEnum.OnePoint
185:                                 && PostBondInspection.PostBondInspectionMode
186:                                 == PostBondInspectionModeEnum.WithoutReferenceSearch)
187:                             {
188:                                 // 判断是否检测背崩
189:                                 if (!this.PostBondInspection.IsDetectBacksideCrack)
190:                                 {
191:                                     return this.WithoutReferResultDeal(
192:                                         this.PostBondInspection.VisionConfig.P1PRName,
193:                                         g0Point4D1);
194:                                 }
195:                                 else
196:                                 {
197:                                     // 定位结果处理
198:                                     if (this.WithoutReferResultDeal(
199:                                             this.PostBondInspection.VisionConfig.P1PRName,
200:                                             g0Point4D1) != ExcuteResult.Success)
201:                                     {
202:                                         return this.WithoutReferResultDeal(
203:                                             this.PostBondInspection.VisionConfig.P1PRName,
204:                                             g0Point4D1);
205:                                     }
206: 
207:                                     PREntity pREntity = (PREntity)VisionEntityRepository.GetInstance()
208:                                         .Find(this.PostBondInspection.VisionConfig.P1PRName);
209: 
210:                                     MatchResult matchResult = (MatchResult)pREntity.AlgResult;
211: 
212:                                     // todo:移动到芯片中心
213: 
214:                                     retry:
215: 
216:                                     // 背崩检测
217:                                     bool isCrack = this.system2Controller.BacksideCrackDetect(
218:                                         matchResult,
219:                                         this.PostBondInspection.VisionConfig.BacsideCrackDetectPRName);
220: 
221:                                     // 处理结果
222:                                     ExcuteResult ret = this.BacksideCrackResultDeal(
223:                                         this.PostBondInspection.VisionConfig.BacsideCrackDetectPRName,
224:                                         isCrack);
225: 
226:                                     if (ret == ExcuteResult.Retry)
227:                                     {
228:                                         goto retry;
229:                                     }
230:                                     else
231:                                     {
232:                                         return ret;
233:                                     }
234:                                 }
235:                             }
236: 
237:                             #endregion
238: 
239:                             #region 两点定位，无参考点
240: 
241:                             AKRSPoint4D g0Point3D2 = g0Point4D1;
242: 
243:                             if (PostBondInspection.MeasurePointNumber == MeasurePointNumberEnum.TwoPoint)
244:                             {
245:                                 g0Point3D2 = this.DefectVision(
246:                                     this.PostBondInspection.VisionConfig.P2VisionPos,
247:                                     this.PostBondInspection.VisionConfig.P2PRName);
248:                             }
249: 
250:                             if (g0Point3D2 == null)
251:                             {
252:                                 return this.defectResult;
253:                             }
254: 
255:                             if (PostBondInspection.MeasurePointNumber == MeasurePointNumberEnum.TwoPoint
256:                                 && PostBondInspection.PostBondInspectionMode
257:                                 == PostBondInspectionModeEnum.WithoutReferenceSearch)
258:                             {
259:                                 return this.WithoutReferResultDeal(
260:                                     this.PostBondInspection.VisionConfig.P2PRName,
261:                                     (g0Point4D1 + g0Point3D2) / 2);
262: 
263:                             }
264: 
265:                             #endregion
266: 
267:                             #region 一点定位，有参考点
268: 
269:                             AKRSPoint4D g0Point3D3 = this.DefectVision(
270:                                 this.PostBondInspection.VisionConfig.P1ReferVisionPos,
271:                                 this.PostBondInspection.VisionConfig.P1ReferName);
272: 
273:                             if (g0Point3D3 == null)
274:                             {
275:                                 return this.defectResult;
276:                             }
277: 
278:                             if (PostBondInspection.ReferencePointNumber == MeasurePointNumberEnum.OnePoint
279:                                 && PostBondInspection.PostBondInspectionMode
280:                                 == PostBondInspectionModeEnum.WithReferenceSearch)
281:                             {
282:                                 return this.WithReferResultDeal(
283:                                     this.PostBondInspection.VisionConfig.P1ReferName,
284:                                     (g0Point4D1 + g0Point3D2) / 2,
285:                                     g0Point3D3);
286: 
287:                             }
288: 
289:                             #endregion
290: 
291:                             #region 两点定位，有参考点
292: 
293:                             AKRSPoint4D g0Point3D4 = this.DefectVision(
294:                                 this.PostBondInspection.VisionConfig.P2ReferVisionPos,
