297:                             if (g0Point3D4 == null)
298:                             {
299:                                 return this.defectResult;
300:                             }
301: 
302:                             return this.WithReferResultDeal(
303:                                 this.PostBondInspection.VisionConfig.P2ReferName,
304:                                 (g0Point4D1 + g0Point3D2) / 2,
305:                                 (g0Point3D3 + g0Point3D4) / 2);
306: 
307:                         #endregion
308:                     }
309:                 }
310:                 else if (PostBondInspection.ApplicationSystem == PostBondApplicationSystemEnum.BLTMeasure)
