336:                 LogHelper.Post(Level.Error, $"流程{this.Name}运行故障", ex, LogCategory.Bond);
337:                 AKRSMessageBoxExt.Show(ex.Message, "Exception", new string[] { "Exception" }, new DialogResult[] { DialogResult.Yes });
338:                 return ExcuteResult.Exception;
