105:         public override ExcuteResult DoWork()
106:         {
107:             this.WorkStart?.Invoke();
108:             this.State = RunStateEnum.Running;
109: 
110:             System2RunTimeProvider.RecordTime("DipFluxActionNode", "Start ----------------");
111: 
112:             try
113:             {
114:                 if (MachineHardwareConfiguration.GetInstance().IsSlideFluxerConfigured == false)
115:                 {
116:                     throw new Exception("未配置刮胶盘硬件！");
117:                 }
118: 
119:                 // 空跑模式
120:                 if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.DryCycle)
121:                 {
122:                     return this.DipFluxActionDryRun();
123:                 }
124: 
125:                 Substrate substrate = this.system2Domain.ActionNodesService.GetCurrentSubstrate();
126: 
127:                 // 获取当前基岛，
128:                 Module curIslandAcupoint = this.system2Domain.ActionNodesService.GetCurrentModule();
129: 
130:                 // 获取当前焊点
131:                 this.bondPosition = this.system2Domain.ActionNodesService.GetCurrentBondPosition();
132: 
133:                 System2RunTimeProvider.RecordTime("DipFluxActionNode", "开始等允许蘸胶信号");
134: 
135:                 // 等允许蘸胶信号
136:                 if (!SignalPool.GetInstance().IsAllowDipFluxSignal.Wait())
137:                 {
138:                     return ExcuteResult.Abort;
139:                 }
140: 
141:                 System2RunTimeProvider.RecordTime("DipFluxActionNode", "接收到允许蘸胶信号");
142: 
143:                 // 防呆;判断刮胶盘有没有在0位
144:                 if (this.slideFluxerController.IsSlideFluxerAtNLimit())
145:                 {
146:                     // 胶盘伸出
147:                     this.slideFluxerController.SlideFluxerOutWaitArrive();
148:                     //throw new Exception("DipFluxActionNode：刮胶盘处于缩回状态！蘸胶失败！");
149:                 }
150: 
151:                 // 蘸胶位
152:                 AKRSPoint3D dipFluxPos =
153:                     this.bondModuleController.ConvertG0ToMachinePos(
154:                         this.bondDevicePara.SlideFluxerParam.SlideFluxerPos);
155: 
156:                 // 力控模式下不用硬补偿
157:                 double distance = component.DipFluxForceMode == ForceModeEnum.Distance ? component.DipDistance : 0;
158: 
159:                 // 实际蘸胶位置要加上吸嘴高度和芯片厚度
160:                 dipFluxPos.Z = dipFluxPos.Z + this.bondHeadController.GetCurrentNozzle().MeasureHeightOffset
161:                                             + component.ComponentThickness + distance;
162: 
163:                 // 蘸胶位置
164:                 AKRSPoint4D dipFlux4DPos = new AKRSPoint4D()
165:                                                {
166:                                                    X = dipFluxPos.X,
167:                                                    Y = dipFluxPos.Y,
168:                                                    Z = dipFluxPos.Z,
169:                                                    T = this.bondHeadController.GetAxisTRealPos()
170:                                                };
171: 
172:                 // 预蘸胶位置
173:                 AKRSPoint4D preDipFlux4DPos = new AKRSPoint4D()
174:                                                   {
175:                                                       X = dipFluxPos.X,
176:                                                       Y = dipFluxPos.Y,
177:                                                       Z = this.component.IsActivateSlowTravelBeforeDip
178:                                                               ? dipFluxPos.Z + component.SlowTravelDistanceBeforeDipFlux
179:                                                               : dipFluxPos.Z,
180:                                                       T = this.bondHeadController.GetAxisTRealPos()
181:                                                   };
182: 
183:                 // 安全高度
184:                 double safelevel = this.bondModuleController.ConvertG0ToMachinePos(this.bondDevicePara.SlideFluxerParam.SlideFluxerRightBottomPos).Z
185:                                    + this.bondHeadController.GetCurrentNozzle().MeasureHeightOffset + 5;
186: 
187:                 // 去预蘸胶位置
188:                 ExcuteResult ret = this.JumpToSlideFluxer(preDipFlux4DPos, safelevel, component.DipMode);
189: 
190:              if (ret != ExcuteResult.Success)
191:              {
192:                  return ret;
193:              }
194: 
195:              System2RunTimeProvider.RecordTime("DipFluxActionNode", "准备开始蘸胶");
196: 
197:                 // 蘸胶
198:                 ret = this.system2Controller.DipFlux(dipFlux4DPos.Z, component);
199: 
200:               if (ret != ExcuteResult.Success)
201:               {
202:                   return ret;
203:               }
204: 
205:                 #region 漏晶检测
206: 
207:                 // 空跑模式不检测
208:                 if (MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle)
209:                 {
210:                 ReCheckVacuum:
211: 
212:                     if (component.IsActiveComponentDetection)
213:                     {
214:                         // 检测真空
215:                         if (!this.bondHeadController.ComponentCheckAfterPickup(this.bondHeadController.GetCurrentNozzle()))
216:                         {
217:                             // 先安全位置
218:                             this.bondHeadController.MoveBondZToSafePos();
219: 
220:                             // 真空报警芯片+1
221:                             component.AddCountOfVacuumError();
222: 
223:                             DialogResult dialogResult = AKRSMessageBoxExt.Show(
224:                                 $"蘸胶后检测到漏晶！请选择如何处理! \r\n",
225:                                 "真空报警",
226:                                 new string[] { "重新检测", "退出", "忽略", "重取" },
227:                                 new DialogResult[]
228:                                     {
229:                                         DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore,
230:                                         DialogResult.Cancel
231:                                     },
232:                                 AlarmLevel.SecondLevel);
233: 
234:                             switch (dialogResult)
235:                             {
236:                                 case DialogResult.Retry:
237:                                     goto ReCheckVacuum;
238: 
239:                                 case DialogResult.Abort:
240:                                     return ExcuteResult.Abort;
241: 
242:                                 case DialogResult.Ignore:
243:                                     break;
244: 
245:                                 case DialogResult.Cancel:
246: 
247:                                     this.bondModuleController.ThrowAction();
248: 
249:                                     // 抛掉的芯片+1
250:                                     this.component.AddCountOfReject();
251: 
252:                                     // 重置前面的动作节点,重新取贴
253:                                     List<ActionNode> actionNodeList = new List<ActionNode>
254:                                                           {
255:                                                               this.system2Domain.BondActionNodeRepository.PickActionNode,
256:                                                               this.system2Domain.BondActionNodeRepository.UpLookCorrectionActionNode
257:                                                           };
258:                                     this.system2Domain.ActionNodesService.SetActionNodeReWork(actionNodeList);
259: 
260:                                     System2RunTimeProvider.IsRepickComponent = true;
261: 
262:                                     return ExcuteResult.Retry;
263:                                         
264:                             }
265:                         }
266:                     }
267:                 }
268: 
269:                 #endregion
270: 
271:                 //// 给刮胶盘发蘸胶完成信号
272:                 //// 现在放到去固精位发
273:                 //SignalPool.GetInstance().BondDipFluxFinishSignal.Set();
274: 
275:                 System2RunTimeProvider.RecordTime("DipFluxActionNode", "Action 完成");
276: 
277:                 return ExcuteResult.Success;
278:             }
279:             catch (Exception ex)
280:             {
281:                 LogHelper.Post(Level.Error, $"流程{this.Name}运行故障", ex, LogCategory.Bond);
282:                 AKRSMessageBoxExt.Show(ex.Message, "Exception", new string[] { "Exception" }, new DialogResult[] { DialogResult.Yes });
283:                 return ExcuteResult.Exception;
284:             }
285:             finally
286:             {
287:                 this.State = RunStateEnum.Stop;
288:                 this.WorkStop?.Invoke();
289:             }
290:         }

