49:         public override ExcuteResult DoWork()
50:         {
51:             this.WorkStart?.Invoke();
52:             this.State = RunStateEnum.Running;
53:             try
54:             {
55:                 System2RunTimeProvider.RecordTime("系统2点胶动作开始执行", "开始 ----------------");
56: 
57:                 #region 前提条件判断
58: 
59:                 // 单步工作
60:                 if (!System2Domain.GetInstance().WaitSingleStep())
61:                 {
62:                     return ExcuteResult.Abort;
63:                 }
64: 
65:                 // 执行点胶前如果点了停止则退出
66:                 if (!Signal.WaitStart())
67:                 {
68:                     return ExcuteResult.Fail;
69:                 }
70: 
71:                 // 执行预点胶
72:                 if (System2Domain.GetInstance().BondActionNodeRepository.S2PreDispenseActionNode.DoWork() != ExcuteResult.Success)
73:                 {
74:                     return ExcuteResult.Alarm;
75:                 }
76: 
77:                 if (!Signal.WaitStart())
78:                 {
79:                     return ExcuteResult.Fail;
80:                 }
81: 
82:                 #endregion
83: 
84:                 System2RunTimeProvider.RecordTime("点胶前置条件通过，准备开始", "开始 ----------------");
85: 
86:                 // 焊点
87:                 BondPosition bondPosition = this.ActionNodesService.GetCurrentBondPosition();
88: 
89:                 // 获取需要执行的图案
90:                 EpoxyApplication correctApplication = this.ActionNodesService.GetCurrentEpoxyApplication();
91: 
92:                 // 焊点在G0中的位置
93:                 AKRSPoint3D point = bondPosition.CoordinateSystem.SelfPosToG0(new AKRSPoint3D(correctApplication.OffsetX, correctApplication.OffsetY, 0));
94: 
95:                 point += bondPosition.GetDispensePositionCompensate();
96: 
97:                 // 空跑模式不出胶
98:                 bool isDrip = MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle;
99: 
100:                 double angle = bondPosition.CoordinateSystem.DegreeInG0() * 180.0 / Math.PI + bondPosition.GetDispenseRotaryCompensate();
101: 
102:                 #region 更换蘸胶吸嘴
103: 
104:                 if (correctApplication.EpoxyApplicationStrategy == EpoxyApplicationTypeEnum.Printting)
105:                 {
106:                     Nozzle nozzle = System2Domain.GetInstance().BondProgram.NozzleShelfProgram.GetNozzleList().Find(it => it.Name == correctApplication.PrintNozzleName);
107:                     if (nozzle == null)
108:                     {
109:                         throw new Exception("蘸胶吸嘴为空，请重新选择");
110:                     }
111:                     else if (!nozzle.IsAssistantSucceed)
112:                     {
113:                         throw new Exception("蘸胶吸嘴未示教完成，请示教完后重试");
114:                     }
115: 
116:                     // 换吸嘴动作
117:                     bool ret = System2Domain.GetInstance().System2Controller.JudgeAndChangeNozzle(correctApplication.PrintNozzleName);
118:                     if (!ret)
119:                     {
120:                         return ExcuteResult.Abort;
121:                     }
122:                 }
123: 
124:                 #endregion
125: 
126:                 // 执行点胶
127:                 if (System2Domain.GetInstance().S2DispenseController.InterpolationApplication(correctApplication, point, isDrip, false, false, angle) != ExcuteResult.Success)
128:                 {
129:                     return ExcuteResult.Alarm;
130:                 }
131: 
132:                 // 修改当前焊点的状态为点胶完成
133:                 bondPosition.S2FinishedStep(this.ActionNodesService.GetCurrentProcessStepName());
134: 
135:                 StatisticsDomain.GetInstance().RefreshDispenseStatistics();
136: 
137:                 #region 点胶完之后看点胶效果
138: 
139:                 if (MachineStateModel.GetInstance().IsVisionPreviousBondPositionInSystem2)
140:                 {
141:                     System2Domain.GetInstance().BondModuleController.CameraMoveToG0Pos(point);
142: 
143:                     while (MachineStateModel.GetInstance().IsVisionPreviousBondPositionInSystem2)
144:                     {
145:                         if (Machine.GetInstance().IsStop())
146:                         {
147:                             MachineStateModel.GetInstance().IsVisionPreviousBondPositionInSystem2 = false;
148:                             break;
149:                         }
150: 
151:                         Thread.Sleep(100);
152:                     }
153:                 }
154: 
155:                 #endregion
156: 
157:                 if (MachineHardwareConfiguration.GetInstance().IsSystem2Dispense)
158:                 {
159:                     if (BondProgram.GetInstance().S2DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.BeforeEveryDispense)
160:                     {
161:                         System2RunTimeProvider.IsFirstDispense = true;
162:                     }
163:                     else if (BondProgram.GetInstance().S2DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.BeforeComingFirstDispense)
164:                     {
165:                         System2RunTimeProvider.IsFirstDispense = false;
166:                     }
167:                 }
168: 
169:                 DispenseRunTimeProvider.RecordTime("系统2点胶结束", "点胶结束 ----------------");
170: 
171:                 System2Domain.GetInstance().BondActionNodeRepository.S2PreDispenseActionNode.LastDispenseTime = DateTime.Now;
172: 
173:                 StatisticsDomain.GetInstance().RefreshS2DispenseStatistics();
174: 
175:                 return ExcuteResult.Success;
176:             }
177:             catch (Exception ex)
178:             {
179:                 LogHelper.Post(Level.Error, $"流程运行故障！", ex, LogCategory.Bond);
180:                 AKRSMessageBoxExt.Show(ex.Message, "异常", new string[] { "异常" }, new DialogResult[] { DialogResult.Yes });
181:                 return ExcuteResult.Exception;
182:             }
183:             finally
184:             {
185:                 this.State = RunStateEnum.Stop;
186:                 this.WorkStop?.Invoke();
187:             }
188:         }

