70:         public override ExcuteResult DoWork()
71:         {
72:             this.WorkStart?.Invoke();
73:             this.State = RunStateEnum.Running;
74:             try
75:             {
76:                 // 判断是否需要执行预点胶动作
77:                 if (!this.IsDispense())
78:                 {
79:                     return ExcuteResult.Success;
80:                 }
81: 
82:                 System2RunTimeProvider.RecordTime("预点胶", $"预点胶开始----------------");
83: 
84:                 // 获取点胶位置的集合
85:                 List<AKRSPoint3D> lists = this.PreDispensePlateProgram.GetEpoxy(
86:                     this.S2DispenserProgram.Dispenser.PreDispense.RepeatPreDispensing);
87: 
88:                 if (lists == null)
89:                 {
90:                     return ExcuteResult.Abort;
91:                 }
92: 
93:                 // 获取预点胶的图案
94:                 EpoxyApplication epoxyApplication = (EpoxyApplication)EpoxyApplicationRepository.GetInstance()
95:                     .Find(this.S2DispenserProgram.Dispenser.PreDispense.EpoxyApplicationName);
96: 
97:                 bool isPrintTool = MachineHardwareConfiguration.GetInstance().IsSystem2ConfigPrintingTool;
98:                 if (isPrintTool)
99:                 {
100:                     if (string.IsNullOrEmpty(epoxyApplication.PrintNozzleName) || epoxyApplication.PrintNozzleName == "Null")
101:                     {
102:                         throw new Exception("蘸胶吸嘴为空，无法执行蘸胶动作");
103:                     }
104: 
105:                     // 换吸嘴动作
106:                     bool ret = System2Domain.GetInstance().System2Controller.ChangeNozzle(epoxyApplication.PrintNozzleName);
107:                     if (!ret)
108:                     {
109:                         return ExcuteResult.Abort;
110:                     }
111:                 }
112: 
113:                 foreach (AKRSPoint3D point in lists)
114:                 {
115:                     // 空跑模式不出胶
116:                     bool isDrip = MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle;
117: 
118:                     // 开始点胶动作
119:                     if (System2Domain.GetInstance().S2DispenseController.InterpolationApplication(epoxyApplication, point, isDrip, true, false,0) != ExcuteResult.Success)
120:                     {
121:                         return ExcuteResult.Alarm;
122:                     }
123:                 }
124: 
125:                 // 获取胶后检测对象
126:                 PostBondInspection postBondInspection = (PostBondInspection)PostBondInspectionRepository.GetInstance()
127:                     .Find(this.S2DispenserProgram.Dispenser.PreDispense.PreDispenseCheckName);
128: 
129:                 if (postBondInspection != null)
130:                 {
131:                     this.CheckEpoxyApplication(postBondInspection, postBondInspection.VisionConfig.P1VisionPos + lists.Last());
132:                 }
133: 
134:                 // 如果是手动模式，相机移动到此处
135:                 if (this.IsManual)
136:                 {
137:                     this.IsManual = false;
138:                     System2Domain.GetInstance().S2DispenseController.VisionMoveToG0Pos(lists[lists.Count - 1]);
139:                 }
140: 
141:                 this.LastDispenseTime = DateTime.Now;
142: 
143:                 System2RunTimeProvider.RecordTime("预点胶", $"预点胶结束----------------");
144:                 return ExcuteResult.Success;
145:             }
146:             catch (Exception ex)
147:             {
148:                 LogHelper.Post(Level.Error, $"流程{this.Name}运行故障！", ex, LogCategory.Dispense);
149:                 AKRSMessageBoxExt.Show(ex.Message, "预点胶异常", new string[] { "异常" }, new DialogResult[] { DialogResult.Yes });
150:                 return ExcuteResult.Exception;
151:             }
152:             finally
153:             {
154:                 this.IsManual = false;
155:                 this.State = RunStateEnum.Stop;
156:                 WorkStop?.Invoke();
157:             }
158:         }

164:         private bool IsDispense()
165:         {
166:             if (!MachineHardwareConfiguration.GetInstance().IsSystem2Dispense)
167:             {
168:                 return false;
169:             }
170: 
171:             // 手动的情况下执行出胶
172:             if (this.IsManual && BondProgram.GetInstance().S2DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.Off)
173:             {
174:                 DialogResult dialogResult = AKRSMessageBoxExt.Show(
175:                     $"预点胶功能未打开，请打开后重试 \r\n",
176:                     "预点胶执行失败报警",
177:                     new string[] { "确认" },
178:                     new DialogResult[] { DialogResult.OK },
179:                     AlarmLevel.SecondLevel);
180:                 return false;
181:             }
182:             else if (this.IsManual)
183:             {
184:                 return true;
185:             }
186:             else if (BondProgram.GetInstance().S2DispenserProgram.Dispenser.PreDispense.PreDispensingMode == PreDispensingModeEnum.Off
187:                 && BondProgram.GetInstance().S2DispenserProgram.Dispenser.PreDispense.PreDispensingTiming == PreDispensingTimingEnum.Off)
188:             {
189:                 return false;
190:             }
191:             else if (System2RunTimeProvider.IsFirstDispense)
192:             {
193:                 return true;
194:             }
195:             else if (BondProgram.GetInstance().S2DispenserProgram.Dispenser.PreDispense.PreDispensingMode == PreDispensingModeEnum.Periodic)
196:             {
197:                 int time = System2Domain.GetInstance().BondProgram.S2DispenserProgram.Dispenser.PreDispense.PreDispensingTimeInterval;
198:                 if ((DateTime.Now - this.LastDispenseTime).TotalMilliseconds > time)
199:                 {
200:                     return true;
201:                 }
202:             }
203: 
204:             return false;
205:         }

