119:         public void ForceControlSet(double forceValue, double pos, double speed, int timeOut = 5, double slowTravelDistanceBeforeTouch = 0)
120:         {
121:             this.CheckZAxisSoftLimit(pos);
122: 
123:             // 单步工作
124:             if (!System2Domain.GetInstance().WaitSingleStep())
125:             {
126:                 return;
127:             }
128: 
129:             // 力值转换,Etel的单位是N，固高的单位是g
130:             double forceReference;
131:             double angle = this.GetAxisTRealPos();
132: 
133:             // 判断驱动器类型 
134:             if (this.bondHead.AxisZ.AxisDrive is ETELAxis)
135:             {
136:                 double initialValue = this.GetBondForceCurrentVal(false);
137: 
138:                 forceReference = ForceCalibrationService.ActualForceToInputForce(forceValue, initialValue, angle);
139: 
140:                 // 这里加速度默认是速度的10倍
141:                 this.bondHead.EtelForceControlSet(forceReference, pos, speed, speed * 10.0, timeOut);
142:             }
143:             else
144:             {            
145:                 // 判定是否小力
146:                 bool isSmallforce = ForceCalibrationService.JudgeIsSmallForce(forceValue);
147: 
148:                 // 切换通道、设置压力参数
149:                 this.ChangeChannelAndSetForceControlPara(isSmallforce);
150: 
151:                 double initialValue = this.GetBondForceCurrentVal(isSmallforce);
152: 
153:                 // 出来的单位是N要换算成g,，所以乘以100
154:                 forceReference = ForceCalibrationService.ActualForceToInputForce(forceValue, initialValue, angle) * 100.0;
155: 
156:                 this.GTForceControlSet(forceReference, pos, slowTravelDistanceBeforeTouch, isSmallforce);
157:             }
158:         }

169:         public void GTForceControlSet(
170:             double forceValue,
171:             double pos,
172:             double slowTravelBeforeTouchDown,
173:             bool isSmallForce = false,
174:             bool isUseActualInitial = false)
175:         {
176:             try
177:             {
178:                this.CheckBeforeForceControlSet(forceValue, slowTravelBeforeTouchDown);
179: 
180:                 // 探底位置=焊点测高位置-二段速距离-固定值
181:                 // 对应固高demoC点
182:                 double limitPos = pos - slowTravelBeforeTouchDown - ForceConfig.GetInstance().ForceControlDebugBToCDistance;
183: 
184:                 double angle = this.GetAxisTRealPos();
185: 
186:                 // 模拟量残值
187:                 // 标定时用的是实时值，其他情况使用固定值
188:                 double initialVal = isUseActualInitial ? this.GetBondForceCurrentVal(isSmallForce) : ForceCalibrationService.GetInitialValByAngle(angle);
189: 
190:                 //Console.WriteLine($"{initialVal}");
191: 
192:                 // 增量
193:                 double increment = forceValue - initialVal;
194: 
195:                 // 获取力控配置,输入参数是g
196:                 ForceConfigItem configItem = isSmallForce
197:                                                  ? ForceConfig.GetInstance().GetSmallForceConfigItem(increment)
198:                                                  : ForceConfig.GetInstance().GetLargeForceConfigItem(increment);
199: 
200:                 short axisNum = (short)this.bondHead.AxisZ.AxisNum;
201: 
202:                 //设置压力参数
203:                 short rtn;
204: 
205:                 GTN.mc.TAdcConfig adcCfg = new GTN.mc.TAdcConfig();
206: 
207:                 // 核号即卡号
208:                 short coreTemp = (short)this.bondHead.AxisZ.CardNum;
209:                 short i = 0;
210: 
211:                 // 设定力控闭环所关联的轴
212:                 double[] gearRatio = new double[24];
213: 
214:                 // 设置压力闭环的工作空间，超过工作空间，切换到位置闭环。压力闭环模式才有效
215:                 short centerSynchEnable = 0;
216:                 int pressRangeTemp, centerPos = 0;
217: 
218:                 GTN.mc.TListInfo listInfoNull = new GTN.mc.TListInfo();
219:                 BondModule bond = new BondModule();
220: 
221:                 // 等待指令流结束
222:                 TCommandListStatus pStatus;
223:                 do
224:                 {
225:                     rtn = GTN.mc.GTN_GetCommandListStatus(coreTemp, 1, out pStatus);
226:                 }
227:                 while (/*pStatus.stopInfo != 10*/pStatus.execute != 0
228:                 && bond.BondAxisX.IsInCommandPosition()
229:                 && bond.BondAxisY.IsInCommandPosition()
230:                 && bond.BondHead.AxisZ.IsInCommandPosition());
231: 
232:                 LogHelper.Post(Level.Info, $"画胶指令完成", LogCategory.Dispense, ViewType.InFileAndUI);
233: 
234: 
235:                 rtn = GuGaoDrive.GTN_GroupStop(coreTemp, 1, ref listInfoNull);
236:                 rtn = GuGaoDrive.GTN_GroupStop(coreTemp, 2, ref listInfoNull);
237:                 rtn = GTN.mc.GTN_StopCommandList(coreTemp, 1, (short)0, ref listInfoNull);
238:                 rtn = GTN.mc.GTN_ClearCommandListData(coreTemp, 1, ref listInfoNull);
239:                 rtn = GTN.mc.GTN_StopCommandList(coreTemp, 2, (short)0, ref listInfoNull);
240:                 rtn = GTN.mc.GTN_ClearCommandListData(coreTemp, 2, ref listInfoNull);
241:                 rtn = GTN.mc.GTN_GroupDisable(coreTemp, 1, ref listInfoNull);
242:                 rtn = GTN.mc.GTN_UngroupAllAxes(coreTemp, 1, ref listInfoNull);
243:                 rtn = GTN.mc.GTN_GroupDisable(coreTemp, 2, ref listInfoNull);
244:                 rtn = GTN.mc.GTN_UngroupAllAxes(coreTemp, 2, ref listInfoNull);
245: 
246:                 // 清除力控状态
247:                 rtn = GTN.mc.GTN_ClearPressStatus(coreTemp, axisNum);
248: 
249:                 #region 设置力控参数
250: 
251: 
252:                 listInfoNull.reserve1 = new short[2];
253:                 listInfoNull.reserve2 = new short[3];
254:                 listInfoNull.reserve3 = new double[4];
255:                 listInfoNull.list = 0;
256:                 GTN.mc.TPressLoopControlPrmCs pressLoopPrm = new GTN.mc.TPressLoopControlPrmCs();
257:                 short setPrmType = GTN.mc.SET_PRESS_LOOP_PRM_TYPE_PRESS_LOOP_CONTROL_PRM;
258:                 pressLoopPrm.controlValueReverse = 1;
259:                 rtn = GTN.mc.GTN_SetPressLoopPrm(coreTemp, axisNum, setPrmType, ref pressLoopPrm, ref listInfoNull);
260: 
261:                 rtn = GTN.mc.GTN_GetPressRange(coreTemp, axisNum, out centerPos, out pressRangeTemp);
262:                 pressRangeTemp = 50000;//50000
263:                 rtn = GTN.mc.GTN_SetPressRange(coreTemp, axisNum, centerSynchEnable, pressRangeTemp);
264: 
265:                 //设定主卡资源个数，MC_AU_ADC --- 非轴模拟量 输入，资源个数为8.
266:                 rtn = GTN.mc.GTN_SetResCount(coreTemp, GTN.mc.MC_AU_ADC, 8);
267:                 //获取模拟量配置参数设定	
268:                 //TAdcConfig adcConfig = new TAdcConfig();
269:                 rtn = GTN.mc.GTN_GetAuAdcConfig(coreTemp, /*1*/channel, out adcCfg);
270:                 short adc = GTN.mc.GTN_GetAdcValue(coreTemp,  /*1*/channel, out short pValue, 1, out uint pClock);
271:                 adcCfg.a = 1;
272:                 adcCfg.b = pValue;
273:                 //关联模拟量输入和力矩闭环的实际力矩值，这里可能需要通过查表来计算实际电流的值比较靠谱，因为模拟量是
274:                 //会有波动的。
275:                 rtn = GTN.mc.GTN_SetAuAdcConfig(coreTemp,  /*1*/channel, ref adcCfg);
276:                 GTN.mc.TPressPrm pressPrm = new GTN.mc.TPressPrm();
277:                 rtn = GTN.mc.GTN_GetPressPrm(coreTemp, axisNum, out pressPrm);
278:                 pressPrm.active = 1;// 压力控制功能打开
279:                 pressPrm.scale = 1;// 保留，物理单位到数子量的脉冲当量
280:                 pressPrm.linkAxis = axisNum;  // 映射力矩控制的关联轴
281:                 rtn = GTN.mc.GTN_SetPressPrm(coreTemp, axisNum, ref pressPrm);
282:                 // 压力控制反馈来源于第1路AU_ADC
283:                 rtn = GTN.mc.GTN_GetPressFeedbackType(coreTemp, axisNum, out short pressFbType, out short pressFbIndex);
284:                 pressFbType = GTN.mc.MC_AU_ADC;
285: 
286:                 pressFbIndex = /*1*/channel;//模拟量输入的第一通道
287:                 rtn = GTN.mc.GTN_SetPressFeedbackType(coreTemp, axisNum, pressFbType, pressFbIndex);
288: 
289:                 // 规划压力清零
290:                 rtn = GTN.mc.GTN_SetPrfPress(coreTemp, axisNum, 0);
291: 
292:                 //设置闭环压力的PID参数
293:                 GTN.mc.TPressPid pressPid, pressPid1;
294:                 rtn = GTN.mc.GTN_GetPressPid(coreTemp, axisNum, out pressPid);
295:                 pressPid.kp = configItem.Kp;
296:                 pressPid.ki = configItem.Ki;
297:                 pressPid.kd = configItem.Kd;
298:                 pressPid.kvff = 0;
299:                 pressPid.kaff = 0;
300:                 pressPid.derivativeLimit = 10000;
