302:                 pressPid.limitMax = 20000;// 控制器输出最大值
303:                 pressPid.limitMin = -20000;// 控制器输出最小值
304:                 rtn = GTN.mc.GTN_SetPressPid(coreTemp, axisNum, ref pressPid);
305:                 rtn = GTN.mc.GTN_GetPressPid(coreTemp, axisNum, out pressPid1);
306: 
307:                 // 模拟量初始值
308:                 //double initialValue = this.GetBondForceCurrentVal(isSmallForce);
309: 
310:                 // 设置压力保护参数，位置闭环模式、压力闭环模式，保护都有效
311:                 // 这个是切换力值，要从标定数据中获取
312:                 // 大力小力的算法不一样
313:                 //double modelChange = isSmallForce == false
314:                 //                         ? ForceCalibrationService.GetForceModelChange(forceValue, configItem)
315:                 //                         : ForceCalibrationService.GetSmallForceModelChange(forceValue, initialValue);
316: 
317:                 double modelChange = ForceCalibrationService.GetForceModelChange(forceValue, configItem);
318: 
319:                 if (modelChange < 0)
320:                 {
321:                     string info = isSmallForce ? "LVDT" : "应变片";
322:                     throw new Exception($"力控切换阈值为负数，请检查{info}模拟量是否为负数！");
323:                 }
324: 
325: 
326:                 rtn = GTN.mc.GTN_GetPressAutoSwitchPrm(coreTemp, axisNum, out GTN.mc.TPressAutoSwitchPrm autoSwitchPrm0);
327:                 autoSwitchPrm0.limit1 = (short)(32767 / maxPress * modelChange - 5);
