196:         public ForceConfigItem GetLargeForceConfigItem(double forceValue)
197:         {
198:             // 排序
199:             this.LargeForceConfigItemList = this.LargeForceConfigItemList.OrderBy(it => it.ForceLowerLimit).ToList();
200: 
201:             foreach (var forceConfigItem in this.LargeForceConfigItemList)
202:             {
203:                 if (forceValue >= forceConfigItem.ForceLowerLimit && forceValue <= forceConfigItem.ForceUpperLimit)
204:                 {
205:                     return forceConfigItem;
206:                 }
207:             }
208: 
209:             // 小于最小模拟量就用最小模拟量的PID
210:             if (forceValue < this.LargeForceConfigItemList[0].ForceLowerLimit)
211:             {
212:                 return this.LargeForceConfigItemList[0];
213:             }
214: 
215:             int count = this.LargeForceConfigItemList.Count;
216:             if (forceValue > this.LargeForceConfigItemList.Select(it => it.ForceUpperLimit).Max())
217:             {              
218:                 // 大于最大模拟量就用最大模拟量的PID
219:                 return this.LargeForceConfigItemList[count - 1];
220:             }
221: 
222:             return null;
223:         }

