35:         public static double ActualForceToInputForce(double force, double initialValue, double angle)
36:         {
37:             // 判定是否小力
38:             bool isSmallForce = JudgeIsSmallForce(force);
39: 
40:             if (isSmallForce == false)
41:             {
42:                 // 如果是大力：通过角度找力控初始值
43:                 initialValue = GetInitialValByAngle(angle);
44:             }
45: 
46:             List<ForceRelateAngleItem> forceRelateAngleList = isSmallForce
47:                                                                   ? ForceCalibrationData.GetInstance().SmallForceRelationList
48:                                                                   : ForceCalibrationData.GetInstance().LargeForceRelationList;
49: 
50:             // 找到离得最近的角度
51:             ForceRelateAngleItem forceRelateAngle = forceRelateAngleList.Aggregate((minItem, nextItem) =>
52:                 Math.Abs(nextItem.Angle - angle) < Math.Abs(minItem.Angle - angle)
53:                     ? nextItem
54:                     : minItem);
55: 
56:             List<TheoreticalForceAndActualForce> theoreticalForceAndActualForceList =
57:                               forceRelateAngle.TheoreticalForceAndActualForceList.ToList();
58: 
59:             // 默认一个初始值
60:             double forceReference = 0;
61: 
62:             int count = theoreticalForceAndActualForceList.Count;
63: 
64:             double lowerLimit = theoreticalForceAndActualForceList[0].CaliTableForce;
65:             double upperLimit = theoreticalForceAndActualForceList[theoreticalForceAndActualForceList.Count - 1].CaliTableForce;
66: 
67:             // 如果列表中的实际力为0，说明没有进行标定
68:             if ((ForceCalibrationData.GetInstance().SmallForceRelationList.Count <= 0 && isSmallForce)
69:                 || (ForceCalibrationData.GetInstance().LargeForceRelationList.Count <= 0 && isSmallForce == false))
70:             {
71:                 throw new Exception("力控标定未完成，请先进行力控标定!");
72:             }
73:             else
74:             {
75:                 // 如果输入的力值超出存储范围，则返回最小力
76:                 if (force < lowerLimit
77:                     || force > upperLimit)
78:                 {
79:                     AKRSXtraMessageBox.Show(
80:                         $"输入力值:{force}g,isSmallForce:{isSmallForce},在{angle}°超出力控范围,最大力值 ：{upperLimit}g, 最小力值:{lowerLimit}g!",
81:                         "异常",
82:                         MessageBoxButtons.OK,
83:                         MessageBoxIcon.Warning);
84: 
85:                     throw new Exception("输入力值超出范围!");
86:                     // return actualForce;
87:                 }
88: 
89:                 // 如果只有一条数据
90:                 if (count == 1)
91:                 {
92:                     forceReference = theoreticalForceAndActualForceList[0].CaliTableForce / 100.0;
93:                     return forceReference;
94:                 }
95: 
96:                 // 根据输入的力值先找到实际力值存储范围，计算系数，再计算对应理论力值
97:                 for (int i = 0; i < count - 1; i++)
98:                 {
99:                     if (force <= theoreticalForceAndActualForceList[i + 1].CaliTableForce && force >= theoreticalForceAndActualForceList[i].CaliTableForce)
100:                     {
101:                         if (theoreticalForceAndActualForceList[i + 1].ForceIncrement == 0)
102:                         {
103:                             throw new Exception("力控模拟量增量为0，请重新进行力控标定!");
104:                         }
105: 
106:                         double k =
107:                             (theoreticalForceAndActualForceList[i + 1].ForceIncrement
108:                              - theoreticalForceAndActualForceList[i].ForceIncrement)
109:                             / (theoreticalForceAndActualForceList[i + 1].CaliTableForce
110:                                - theoreticalForceAndActualForceList[i].CaliTableForce);
111: 
112:                         double b = theoreticalForceAndActualForceList[i].ForceIncrement
113:                                    - k * theoreticalForceAndActualForceList[i].CaliTableForce;
114: 
115:                         // 这里除以100是把g转成N
116:                         forceReference = (k * force + b + initialValue) / 100.0;
117: 
118:                         break;
119:                     }
120:                 }
121: 
122:                 if (isSmallForce)
123:                 {
124:                     if (forceReference > ForceConfig.GetInstance().SmallForceConfigItemList.Last().ForceUpperLimit)
125:                     {
126:                         throw new Exception("力控输入模拟量超出量程，请联系设备供应商!");
127:                     }
128:                 }
129: 
130:                 return forceReference;
131:             }
132:         }

207:         public static double ForceIncrementToActualForce(double forceIncrement, bool isSmallForce, double angle)
208:         {
209:             List<ForceRelateAngleItem> forceRelateAngleList = isSmallForce
210:                                                                   ? ForceCalibrationData.GetInstance().SmallForceRelationList
211:                                                                   : ForceCalibrationData.GetInstance().LargeForceRelationList;
212: 
213:             try
214:             {
215:                 // 找到离得最近的角度
216:                 ForceRelateAngleItem forceRelateAngle = forceRelateAngleList.Aggregate((minItem, nextItem) =>
217:                     Math.Abs(nextItem.Angle - angle) < Math.Abs(minItem.Angle - angle)
218:                         ? nextItem
219:                         : minItem);
220: 
221:                 List<TheoreticalForceAndActualForce> theoreticalForceAndActualForceList =
222:                     forceRelateAngle.TheoreticalForceAndActualForceList.ToList();
223: 
224:                 // 默认一个初始值
225:                 double forceReference = 0;
226: 
227:                 int count = theoreticalForceAndActualForceList.Count;
228: 
229:                 // 如果列表中的实际力为0，说明没有进行标定
230:                 if (count == 0) 
231:                 {
232:                     return 0;
233:                 }
234: 
235:                 // 如果只有一条数据
236:                 if (count == 1)
237:                 {
238:                     return theoreticalForceAndActualForceList[0].CaliTableForce;
239:                 }
240: 
241:                 // 增量低于2默认焊头没有接触 这个是为了让力控实时曲线好看一点
242:                 if (forceIncrement < 2)
243:                 {
244:                     return 0;
245:                 }
246: 
247:                 // 增量的最大最小值
248:                 double lowerLimit = theoreticalForceAndActualForceList.Select(it => it.ForceIncrement).Min();
249:                 double upperLimit = theoreticalForceAndActualForceList.Select(it => it.ForceIncrement).Max();
250:                 {
251:                     // 如果输入的力值小于标定的增量的最小值
252:                     if (forceIncrement < lowerLimit)
253:                     {
254:                         return theoreticalForceAndActualForceList[0].CaliTableForce / theoreticalForceAndActualForceList[0].ForceIncrement * forceIncrement;
255:                     }
256: 
257:                     // 如果输入的力值大于标定的最大值,按照最后一段去计算
258:                     if (forceIncrement > upperLimit)
259:                     {
260:                         double k =
261:                             (theoreticalForceAndActualForceList[count - 1].CaliTableForce
262:                              - theoreticalForceAndActualForceList[count - 2].CaliTableForce)
263:                             / (theoreticalForceAndActualForceList[count - 1].ForceIncrement
264:                                - theoreticalForceAndActualForceList[count - 2].ForceIncrement);
265: 
266:                         double b = theoreticalForceAndActualForceList[count - 1].CaliTableForce - k * theoreticalForceAndActualForceList[count - 1].ForceIncrement;
267: 
268:                         forceReference = k * forceIncrement + b;
269: 
270:                         return forceReference;
271:                     }
272: 
273:                     // 根据输入的力值先找到实际力值存储范围，计算系数，再计算对应理论力值
274:                     for (int i = 0; i < count - 1; i++)
275:                     {
276:                         if (forceIncrement <= theoreticalForceAndActualForceList[i + 1].ForceIncrement && forceIncrement >= theoreticalForceAndActualForceList[i].ForceIncrement)
277:                         {
278:                             double k = (theoreticalForceAndActualForceList[i + 1].CaliTableForce - theoreticalForceAndActualForceList[i].CaliTableForce)
279:                                        / (theoreticalForceAndActualForceList[i + 1].ForceIncrement - theoreticalForceAndActualForceList[i].ForceIncrement);
280: 
281:                             double b = theoreticalForceAndActualForceList[i].CaliTableForce - k * theoreticalForceAndActualForceList[i].ForceIncrement;
282: 
283:                             forceReference = k * forceIncrement + b;
284:                             break;
285:                         }
286:                     }
287: 
288:                     return forceReference;
289:                 }
290:             }
291:             catch (Exception ex)
292:             {
293:                 LogHelper.Post(
294:             Level.Error,
295:             $"焊头力控增量转实际力异常：" + ex.ToString,
296:             LogCategory.Bond,
297:             ViewType.InFileAndUI);
298:                
299:                // 直接返回异常数据
300:                 return 999;
301:             }
302:         }

