320:             if (inputValue > upperLimit || inputValue <= 0)
321:             {
322:                 throw new Exception($"力控输入的模拟量{inputValue}超过阈值0~{upperLimit}");
323:             }
324: 
325:             if (initialValue > inputValue)
326:             {
327:                 throw new Exception($"力控输入的模拟量{inputValue}小于当前初始值{initialValue}");
328:             }
329: 
330:             // 分成三份每一份的间隔
331:             double pitch = (upperLimit - lowerLimit) / 3.0;
332: 
333:             if (inputValue < lowerLimit + pitch)
334:             {
335:                 // 小力
336:                 modelChangeForce = inputValue - (inputValue - initialValue) * 0.5;
337:             }
338:             else if (inputValue >= lowerLimit + pitch && inputValue < lowerLimit + pitch * 2)
339:             {
340:                 // 中力
341:                 modelChangeForce = inputValue - (inputValue - initialValue) * 0.1;
342:             }
343:             else if (inputValue >= lowerLimit + pitch * 2 && inputValue <= upperLimit)
344:             {
345:                 // 大力
346:                 modelChangeForce = inputValue - (inputValue - initialValue) * 0.01;
347:             }
348: 
349:             // 单位是kg这里要除以1000
350:             return modelChangeForce / 1000.0;
351:         }

359:         public static double GetForceModelChange(double inputValue, ForceConfigItem forceConfigItem)
360:         {
361:             double modelChangeForce =
362:                 inputValue - (forceConfigItem.ForceLowerLimit - forceConfigItem.ChangeForceLowerLimit);
363: 
364:             //double modelChangeForce = inputValue * forceConfigItem.ChangeForceK + forceConfigItem.ChangeForceB;
365: 
366:             //if ((inputValue - modelChangeForce) > 10)
367:             //{
368:             //    modelChangeForce = inputValue - 10;
369:             //}
370: 
371:             // 单位是kg这里要除以1000
372:             return modelChangeForce / 1000.0;
373:         }

