381:         {
382:             if (inputValue < 0) 
383:             {
384:                 throw new Exception($"输入力值为负数,大小力判断失败！");
385:             }
386: 
387:             if (inputValue < ForceConfig.GetInstance().ForceBoundary)
388:             {
389:                 return true;
390:             }
391: 
392:             return false;
393:         }

400:         public static double GetInitialValByAngle(double angle)
401:         {
402:             return
403:                 ForceCalibrationData.GetInstance().ForceInitialValDic.ToList().Aggregate(
404:                     (minItem, nextItem) =>
405:                         Math.Abs(nextItem.Key - angle) < Math.Abs(minItem.Key - angle) ? nextItem : minItem).Value;
406:         }

